#!name=Spotify(>=iOS15)
#!author=queitstart pro
#!date=2026-11-21
#!desc=2025.06.27 部分解锁premium,音质不能设置为超高(建议登录后再打开脚本,重启app等待脚本生效)
#!format=sgmodule

[Script]
spotify-json = type=http-request,pattern=^https:\/\/(spclient\.wg\.spotify\.com|.*-spclient\.spotify\.com(:443)?)\/(artistview\/v1\/artist|album-entity-view\/v2\/album)\/,requires-body=0,script-path=https://raw.githubusercontent.com/qs-toolkit/qingqi-mitm-rules/main/scripts/41cf1074770cdef3948baa12ff4a8db9045d1cac888714c8b7e69909eb531bc9.js
spotify-proto = type=http-response,pattern=^https:\/\/(spclient\.wg\.spotify\.com|.*-spclient\.spotify\.com(:443)?)\/(bootstrap\/v1\/bootstrap|user-customization-service\/v1\/customize)$,requires-body=1,binary-body-mode=1,max-size=0,script-path=https://raw.githubusercontent.com/qs-toolkit/qingqi-mitm-rules/main/scripts/2e6850e888d092905c766f0bbedc4b4afb9a712330970cc1265105d7fb4995d0.js,script-update-interval=0

[Header Rewrite]
http-request ^https:\/\/(spclient\.wg\.spotify\.com|.*-spclient\.spotify\.com(:443)?)\/user-customization-service\/v1\/customize$ header-del if-none-match

[MITM]
hostname = %APPEND% spclient.wg.spotify.com, *spclient.spotify.com
